import numpy as np

rng = np.random.default_rng(0)
params = [
    (rng.standard_normal((4, 8)) * 0.5, np.zeros(8)),   # input(4) -> hidden(8)
    (rng.standard_normal((8, 4)) * 0.5, np.zeros(4)),   # hidden(8) -> hidden(4)
    (rng.standard_normal((4, 2)) * 0.5, np.zeros(2)),   # hidden(4) -> output(2)
]


def linear(x, W, b):
    return x @ W + b


def relu(x):
    return np.maximum(0, x)


def softmax(z):
    e = np.exp(z - z.max(axis=1, keepdims=True))
    return e / e.sum(axis=1, keepdims=True)


def forward(x, params):
    shapes = [x.shape]
    for W, b in params[:-1]:
        x = relu(linear(x, W, b))
        shapes.append(x.shape)
    W, b = params[-1]
    probs = softmax(linear(x, W, b))
    shapes.append(probs.shape)
    return probs, shapes


x = rng.standard_normal((5, 4))      # a batch of 5 samples
result = forward(x, params)
if result is None:
    print("forward() returned None")
else:
    probs, shapes = result
    print("shapes:", shapes)
    print("probabilities:")
    print(np.round(probs, 3))
